package com.example.obliviondescent;

import java.util.List;
import java.util.Map;

/**
 * Holds all data generated by Gemini AI for one floor range.
 * Includes enemy templates, per-floor shop items and boss info.
 */
public class BatchResult {
    /** Pool of unique enemy templates for this floor range. */
    public List<EnemyTemplate>       enemyPool;         // 5 unique enemies for this range
    /** Mapping of floor number to 6 shop items. */
    public Map<Integer, List<ShopItem>> shopByFloor;    // floor number → 6 shop items
    /** Generated boss name. */
    public String bossName;
    /** Generated boss title. */
    public String bossTitle;
    /** Boss display colour. */
    public int    bossColor;
    /** Boss stat multipliers on top of floor scaling. */
    public float  bossHpMultiplier, bossDmgMultiplier;
    /** Boss archetype: how it fights and looks. */
    public Enemy.BossKind bossKind;

    /**
     * Creates a new batch result with all generated data.
     * @param enemyPool enemy template pool
     * @param shopByFloor per-floor shop items map
     * @param bossName boss name
     * @param bossTitle boss title
     * @param bossColor boss display colour
     */
    public BatchResult(List<EnemyTemplate> enemyPool,
                       Map<Integer, List<ShopItem>> shopByFloor,
                       String bossName, String bossTitle, int bossColor) {
        this.enemyPool   = enemyPool;
        this.shopByFloor = shopByFloor;
        this.bossName    = bossName;
        this.bossTitle   = bossTitle;
        this.bossColor   = bossColor;
    }
}